import os
import yaml
import pytest

from kubernetes.base.config.kube_config import load_kube_config, list_kube_config_contexts, KubeConfigMerger


def write_yaml(path, data):
    with open(path, 'w') as f:
        yaml.safe_dump(data, f, default_flow_style=False)


@pytest.mark.usefixtures("tmp_path")
def test_merge_current_context_from_later_file(tmp_path, monkeypatch):
    # Create cluster.yaml (no current-context)
    cluster = {
        "apiVersion": "v1",
        "kind": "Config",
        "clusters": [
            {
                "name": "kube.example.com",
                "cluster": {
                    "certificate-authority-data": "doesnotmatter",
                    "server": "https://kube.example.com:6443",
                },
            }
        ],
    }
    cluster_yaml = tmp_path / "cluster.yaml"
    write_yaml(cluster_yaml, cluster)

    # Create user.yaml
    user = {
        "apiVersion": "v1",
        "kind": "Config",
        "users": [
            {"name": "kube.example.com"}
        ],
    }
    user_yaml = tmp_path / "user.yaml"
    write_yaml(user_yaml, user)

    # Create context.yaml (has current-context)
    context = {
        "apiVersion": "v1",
        "kind": "Config",
        "contexts": [
            {
                "name": "kube.example.com",
                "context": {
                    "cluster": "kube.example.com",
                    "user": "kube.example.com",
                    "namespace": "kube-system",
                },
            }
        ],
        "current-context": "kube.example.com",
    }
    context_yaml = tmp_path / "context.yaml"
    write_yaml(context_yaml, context)

    # Build KUBECONFIG with context last (order should not matter)
    kc = os.pathsep.join([str(cluster_yaml), str(user_yaml), str(context_yaml)])
    monkeypatch.setenv("KUBECONFIG", kc)

    # load_kube_config should not raise and active context should be kube.example.com
    load_kube_config()
    contexts, current = list_kube_config_contexts()
    # Ensure the context is present
    names = {c.get("name") for c in contexts}
    assert "kube.example.com" in names
    assert current.get("name") == "kube.example.com"


@pytest.mark.usefixtures("tmp_path")
def test_last_file_wins_empty_current_context(tmp_path, monkeypatch):
    # First file sets a non-empty current-context
    ctx1 = {
        "apiVersion": "v1",
        "kind": "Config",
        "contexts": [
            {
                "name": "ctx1",
                "context": {"cluster": "c", "user": "u"},
            }
        ],
        "current-context": "ctx1",
    }
    ctx1_yaml = tmp_path / "ctx1.yaml"
    write_yaml(ctx1_yaml, ctx1)

    # Second file sets current-context to empty string
    ctx2 = {
        "apiVersion": "v1",
        "kind": "Config",
        "contexts": [
            {
                "name": "ctx2",
                "context": {"cluster": "c", "user": "u"},
            }
        ],
        "current-context": "",
    }
    ctx2_yaml = tmp_path / "ctx2.yaml"
    write_yaml(ctx2_yaml, ctx2)

    kc = os.pathsep.join([str(ctx1_yaml), str(ctx2_yaml)])
    monkeypatch.setenv("KUBECONFIG", kc)

    # Use the merger directly to inspect merged value regardless of loader behavior
    merger = KubeConfigMerger(kc)
    assert "current-context" in merger.config.value
    assert merger.config.value["current-context"] == ""


@pytest.mark.usefixtures("tmp_path")
def test_last_file_wins_non_empty_override(tmp_path, monkeypatch):
    first = {
        "apiVersion": "v1",
        "kind": "Config",
        "contexts": [
            {
                "name": "ctxA",
                "context": {"cluster": "cA", "user": "uA"},
            }
        ],
        "clusters": [{"name": "cA", "cluster": {"server": "https://kube.example.com"}}],
        "users": [{"name": "uA"}],
        "current-context": "ctxA",
    }
    second = {
        "apiVersion": "v1",
        "kind": "Config",
        "contexts": [
            {
                "name": "ctxB",
                "context": {"cluster": "cB", "user": "uB"},
            }
        ],
        "clusters": [{"name": "cB", "cluster": {"server": "https://kube.example.com"}}],
        "users": [{"name": "uB"}],
        "current-context": "ctxB",
    }
    first_yaml = tmp_path / "first.yaml"
    second_yaml = tmp_path / "second.yaml"
    write_yaml(first_yaml, first)
    write_yaml(second_yaml, second)

    kc = os.pathsep.join([str(first_yaml), str(second_yaml)])
    monkeypatch.setenv("KUBECONFIG", kc)

    contexts, current = list_kube_config_contexts()
    assert current.get("name") == "ctxB"

